('11111111-1111-1111-1111-200000000022', '11111111-1111-1111-1111-111111111111', 'Feature QA', 'Upload Wizard', 'Functionality', 'Portfolio upload feature supports batch multi-image upload', 'Verify a creator can select and upload up to 20 images in a single batch with individual progress indicators.', 'Batch of 20 images uploads with per-file progress and a combined success/failure summary.', '["Supports up to 20 files per batch", "Per-file progress shown", "Partial failure summary displayed"]', 'Functional Spec', 'Automated', 'High', 'Passed', '', true, now() - interval '8 days'),
('11111111-1111-1111-1111-200000000023', '11111111-1111-1111-1111-111111111111', 'Feature QA', 'Recruiter Dashboard', 'Functionality', 'Recruiter saved-search feature emails weekly digest of new matches', 'Verify saved search criteria trigger a weekly digest email containing newly matching creators.', 'Digest email sent weekly, containing only creators added since the previous digest.', '["Digest scheduled weekly", "No duplicate creators across digests", "Unsubscribe link present"]', 'Functional Spec', 'Automated', 'Medium', 'In Progress', 'Email template built; scheduler job pending.', true, now() - interval '7 days'),
('11111111-1111-1111-1111-200000000024', '11111111-1111-1111-1111-111111111111', 'Feature QA', 'Explore Feed', 'User Experience', 'Follow creator feature updates feed personalization instantly', 'A reviewer follows a creator and evaluates how quickly and clearly the Explore feed reflects that change.', 'Followed creator content appears in a "Following" filter immediately, without requiring a page refresh.', '["Follow reflected without refresh", "Following filter tab discoverable", "Unfollow reverses instantly"]', 'UX Review', 'Human Review', 'Medium', 'Not Started', '', true, now() - interval '6 days'),
