('22222222-2222-2222-2222-200000000031', '22222222-2222-2222-2222-222222222222', 'Release QA', 'Global', 'Accessibility', 'Automated axe-core scan reports zero critical violations pre-release', 'Run axe-core across all primary teacher-facing templates as part of the release checklist.', 'Zero "critical" or "serious" severity violations reported.', '["Zero critical violations", "Zero serious violations", "Report attached to release notes"]', 'A11y Audit', 'Automated', 'Critical', 'Passed', '', true, now() - interval '1 day'),
('22222222-2222-2222-2222-200000000032', '22222222-2222-2222-2222-222222222222', 'Release QA', 'Parent Notifications', 'Functionality', 'SMS/email notification integration verified in staging environment', 'Verify the SMS/email provider integration correctly sends and logs notifications in the staging environment.', 'Test notifications sent and logged correctly for both SMS and email channels in staging.', '["SMS test message delivered", "Email test message delivered", "Delivery logged for audit"]', 'Integration Test', 'Automated', 'High', 'Not Started', '', true, now() - interval '1 day'),
('22222222-2222-2222-2222-200000000033', '22222222-2222-2222-2222-222222222222', 'Release QA', 'Global', 'User Experience', 'Release notes reviewed for clarity with non-technical teacher audience', 'A reviewer reads the drafted release notes from the perspective of a non-technical teacher user.', 'Release notes are understandable without technical background and lead with the teacher-facing benefit.', '["No technical jargon", "Leads with teacher benefit", "Screenshots included where helpful"]', 'Content Review', 'Human Review', 'Low', 'Not Started', '', true, now() - interval '20 hours'),
('22222222-2222-2222-2222-200000000034', '22222222-2222-2222-2222-222222222222', 'Release QA', 'Global', 'Functionality', 'Data backup/rollback plan validated before term-start rollout', 'Verify a full backup and rollback rehearsal completes successfully before the school-term rollout window.', 'Backup completes and rollback restores prior state without attendance data loss in staging rehearsal.', '["Backup completes successfully", "Rollback restores prior state", "No attendance data loss in rehearsal"]', 'Release Checklist', 'Automated', 'Critical', 'Passed', '', true, now() - interval '18 hours'),
